Let $M_1$, $M_2$, and $M_3$ be the midpoints of $AP$, $BP$, and $CP$, respectively.  Then as a midline in triangle $PBC$, $M_2 M_3$ is parallel to $BC$, and half the length of $BC$.

[asy]
import geometry;

unitsize(2 cm);

pair A, B, C, P;
pair[] G, M;

A = (1,3);
B = (0,0);
C = (4,0);
P = (2,1);
G[1] = (P + B + C)/3;
G[2] = (P + C + A)/3;
G[3] = (P + A + B)/3;
M[1] = (P + A)/2;
M[2] = (P + B)/2;
M[3] = (P + C)/2;

draw(A--B--C--cycle);
draw(A--P);
draw(B--P);
draw(C--P);
draw(A--M[2]);
draw(A--M[3]);
draw(G[2]--G[3]);
